"""Day 10: deterministic recommendations. Every item comes from calculated state; nothing is generated by a model.

Rules and thresholds are PROPOSED (not validated). Evidence that is missing withholds the rule instead of guessing.
"""
from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction
from typing import List, Optional, Tuple

from domain.clock import lagos_date
from domain.money import Money, round_fraction
from financial_twin.twin import TwinSnapshot

STEP = Money(500_00)                     # round suggestions to ₦500
RUNWAY_TRIGGER_DAYS = 30
CUT_SHARE = Fraction(1, 5)               # suggest cutting 20% of weekly discretionary spend
SET_ASIDE_SHARE = Fraction(1, 5)         # suggest setting aside 20% of the next income
RECURRING_SHARE = Fraction(1, 20)        # a recurring cost worth 5%+ of monthly spending deserves a review
BILL_LOOKAHEAD = 14


@dataclass(frozen=True)
class Recommendation:
    id: str
    kind: str                            # prepare_bill | reduce_spending | set_aside | build_cushion | review_recurring | goal_too_aggressive
    priority: int                        # 1 = most urgent
    title: str
    amount: Optional[Money]
    because: Tuple[str, ...]
    effect: Optional[str] = None         # engine-computed consequence, e.g. extra days of runway
    confidence: str = "medium"


@dataclass(frozen=True)
class RecommendationSet:
    items: Tuple[Recommendation, ...]
    withheld: Tuple[str, ...]            # rules that could not run, with the missing evidence


def _floor(m: Money) -> Money:
    return m.floor_to(STEP)


def recommend(s: TwinSnapshot, max_items: int = 5) -> RecommendationSet:
    out: List[Recommendation] = []
    withheld: List[str] = []
    today = lagos_date(s.as_of)
    total, inf = s.total, s.inferred
    pos = s.position()

    # 1. bills that the balance cannot cover soon
    if total is not None:
        due = [o for o in s.obligations if 0 < (o.due - today).days <= BILL_LOOKAHEAD]
        bills = Money(sum(o.amount.minor for o in due), total.currency)
        if due and total < bills:
            gap = (bills - total).ceil_to(STEP)
            first = min(due, key=lambda o: o.due)
            out.append(Recommendation("prepare_bill", "prepare_bill", 1, f"Find {gap} before {first.due:%d %b} for upcoming bills", gap,
                                      (f"bills due in {BILL_LOOKAHEAD} days: {bills}", f"connected money: {total}"), None, "high"))
    else:
        withheld.append("bills: connected money is unknown")

    # 2. runway is short: trim discretionary spending
    r = inf.runway
    if inf.burn.per_day is not None and inf.essential_per_day is not None and r.days is not None:
        if r.days < RUNWAY_TRIGGER_DAYS and not r.capped:
            weekly_disc = max(Fraction(0), (Fraction(inf.burn.per_day) - Fraction(inf.essential_per_day)) * 7)
            cut = _floor(round_fraction(weekly_disc * CUT_SHARE))
            if cut.minor >= STEP.minor:
                effect = None
                try:
                    w = s.simulate("spend_less_weekly", cut)
                    if w.base.days is not None and w.scenario.days is not None:
                        effect = f"about {w.scenario.days - w.base.days:.1f} more days of runway"
                except ValueError:
                    pass
                out.append(Recommendation("reduce_spending", "reduce_spending", 2, f"Spend {cut} less each week on non-essentials", cut,
                                          (f"your money lasts about {r.days:.1f} days at the current pace",
                                           "this cut is 20% of weekly non-essential spending"), effect, inf.burn.confidence))
            else:
                withheld.append("reduce_spending: non-essential spending is too small to cut")
    else:
        withheld.append("reduce_spending: spending estimate or essentials unknown")

    # 3. cushion below target: set aside from the next income, else build it
    if total is not None and inf.cushion is not None and total < inf.cushion:
        gap = inf.cushion - total
        nxt = min((x for x in s.streams if 0 < (x.next_expected - today).days <= 30), key=lambda x: x.next_expected, default=None)
        if nxt is not None:
            amt = _floor(round_fraction(Fraction(min(gap.minor, int(nxt.typical.minor * SET_ASIDE_SHARE)))))
            if amt.minor >= STEP.minor:
                out.append(Recommendation("set_aside", "set_aside", 2, f"Set aside {amt} when {nxt.name} arrives on {nxt.next_expected:%d %b}", amt,
                                          (f"emergency cushion target: {inf.cushion}", f"you are {gap} short of it"), None, "medium"))
        else:
            out.append(Recommendation("build_cushion", "build_cushion", 3, f"Build your emergency cushion: {gap} to go", gap,
                                      (f"emergency cushion target: {inf.cushion}", "no income is expected in the next 30 days"), None, "medium"))

    # 4. recurring costs worth a look
    g = s.genome()
    if inf.burn.per_day is not None and g.recurring:
        monthly_burn = Fraction(inf.burn.per_day) * 30
        for rec in g.recurring:
            monthly = Fraction(rec.typical_minor) * (Fraction(13, 3) if rec.cadence == "weekly" else 1)
            if monthly_burn > 0 and monthly / monthly_burn >= RECURRING_SHARE:
                out.append(Recommendation(f"review_{rec.label}", "review_recurring", 3, f"Review your {rec.cadence} {rec.label} payment",
                                          Money(rec.typical_minor), (f"seen {rec.occurrences} times at about {Money(rec.typical_minor)}",
                                                                      f"about {float(monthly / monthly_burn * 100):.0f}% of monthly spending"), None, "medium"))
    elif not g.recurring:
        withheld.append("review_recurring: no recurring payments detected yet")

    # 5. goals that ask for more than is safe
    if pos.goals and pos.safe_flexible is not None and pos.goals_required_horizon > pos.safe_flexible:
        out.append(Recommendation("goal_too_aggressive", "goal_too_aggressive", 2,
                                  "Your savings target is too aggressive for now: lower it or move the deadline",
                                  pos.safe_flexible, (f"goals need {pos.goals_required_horizon} over {pos.horizon_days} days",
                                                      f"safe flexible money is {pos.safe_flexible}"), None, "medium"))
    elif pos.goals and pos.safe_flexible is None:
        withheld.append("goal_too_aggressive: safe flexible money unknown")

    out.sort(key=lambda x: (x.priority, x.id))
    return RecommendationSet(tuple(out[:max_items]), tuple(withheld))
